sys_transform_script.script:
(function runTransformScript(source, map, log, target) {

    var RELATED_INDICATOR_FIELD = 'x_doppe_doppel_t_0_related_indicator';
    if (!target || !target.sys_id) {
        log.info('Doppel onAfter: no target record (row was likely ignored onBefore) — skipping.');
        return;
    }
    var indicatorSysId = target.sys_id.toString();

    // (a) Link observable ↔ indicator through the platform M2M table (sn_ti_m2m_observable_indicator)
    var entity = source.u_entity ? source.u_entity.toString() : '';
    if (entity) {
        var obs = new GlideRecord('sn_ti_observable');
        obs.addQuery('value', entity);
        obs.setLimit(1);
        obs.query();
        if (obs.next()) {
            var link = new GlideRecord('sn_ti_m2m_observable_indicator');
            link.addQuery('observable', obs.getUniqueValue());
            link.addQuery('indicator', indicatorSysId);
            link.setLimit(1);
            link.query();
            if (!link.hasNext()) {
                link.initialize();
                link.setValue('observable', obs.getUniqueValue());
                link.setValue('indicator', indicatorSysId);
                if (!link.insert()) log.error('Doppel onAfter: could not link observable ' + entity + ' to indicator ' + indicatorSysId);
            }
        } else {
            log.error('Doppel onAfter: observable not found for ' + entity + ' while linking ' + indicatorSysId);
        }
    }

    // NEW (refactor, dual-write): mark the indicator as Doppel's (sn_ti_m2m_indicator_source)
    var firstSeen = source.u_created_at ? source.u_created_at.toString().substring(0, 10) : '';
    var lastSeen = source.u_last_activity_timestamp ? source.u_last_activity_timestamp.toString().substring(0, 10) : '';
    new x_doppe_doppel_t_0.DoppelIOCImport().recordDoppelIndicator(indicatorSysId, firstSeen, lastSeen);

    // (b) entity_content → metadata: every field of every top-level key, named <prefix><field>.
    // Unknown keys (e.g. email, crypto) get "entity_<key>_".
    var entityContent = null;
    try {
        entityContent = source.u_entity_content ? JSON.parse(source.u_entity_content.toString()) : null;
    } catch (e) {
        log.error('Doppel onAfter: failed to parse entity_content for indicator ' + indicatorSysId + ': ' + e.message);
    }

    var PREFIX = {
        root_domain: 'entity_', telco: 'entity_telco_', social_media_user: 'entity_social_',
        social_media_post: 'entity_post_', mobile_app: 'entity_app_', ecommerce: 'entity_ecom_',
        advertisement_data: 'entity_ad_', cred_leaks: 'entity_leak_', credit_card_leaks: 'entity_card_'
    };
    var extractedEntityFields = {};
    for (var key in (entityContent || {})) {
        var section = entityContent[key];
        if (!section || typeof section != 'object') continue;
        var prefix = PREFIX[key] || ('entity_' + key + '_');
        for (var field in section) {
            var v = section[field];
            if (field == 'mx_records' && Array.isArray(v))
                v = v.map(function (mx) { return mx.exchange + ' (pref ' + mx.preference + ')'; });
            if (Array.isArray(v))
                v = v.map(function (x) { return (x && typeof x == 'object') ? JSON.stringify(x) : x; }).join(', ');
            else if (v && typeof v == 'object')
                v = JSON.stringify(v);
            v = (v == null) ? '' : String(v);
            if (v && v != '{}') extractedEntityFields[prefix + field] = v.substring(0, 255);
        }
    }

    // (c) Upsert sn_ti_indicator_metadata — names unchanged, values from u_ columns
    var metaFields = {
        severity: source.u_severity,
        score: source.u_score,
        brand: source.u_brand,
        product: source.u_product,
        queue_state: source.u_queue_state,
        entity_state: source.u_entity_state,
        doppel_link: source.u_doppel_link,
        platform: source.u_platform,
        source: source.u_source,
        last_activity_timestamp: source.u_last_activity_timestamp,
        assignee: source.u_assignee,
        uploaded_by: source.u_uploaded_by,
        created_at: source.u_created_at,
        screenshot_url: source.u_screenshot_url,
        message: source.u_message,
        alert_summary: source.u_alert_summary,
        tags: source.u_tags,
        audit_logs: source.u_audit_logs
    };
    for (var k in extractedEntityFields) metaFields[k] = extractedEntityFields[k];

    for (var fieldName in metaFields) {
        var rawVal = metaFields[fieldName];
        if (rawVal == null || rawVal.toString() === '') continue;
        var val = rawVal.toString();

        var meta = new GlideRecord('sn_ti_indicator_metadata');
        meta.addQuery('indicator', indicatorSysId);
        meta.addQuery('name', fieldName);
        meta.query();
        if (meta.next()) {
            meta.setValue('value', val);
            meta.update();
        } else {
            meta.initialize();
            meta.setValue('indicator', indicatorSysId);
            meta.setValue('name', fieldName);
            meta.setValue('value', val);
            meta.insert();
        }
    }

})(source, map, log, target);
